  ('ASRS-V1.1/003', 'hi', 'आपको नियुक्तियों या दायित्वों को याद रखने में कितनी बार समस्या होती है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('ASRS-V1.1/003', 'mr', 'तुम्हाला भेटी किंवा जबाबदाऱ्या लक्षात ठेवण्यात किती वेळा समस्या येते?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
