  ('ASRS-V1.1/008', 'hi', 'जब आप उबाऊ या दोहरावदार काम कर रहे होते हैं तो आप कितनी बार अपना ध्यान केंद्रित नहीं रख पाते हैं?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
