  ('PFS-16/015', 'mr', 'थकव्यामुळे मी माझ्या दिवसात मला वाटते त्यापेक्षा कमी काम करतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PFS-16/016', 'hi', 'मैं इतनी थक जाती हूँ कि जहाँ भी हूँ लेट जाना चाहती हूँ।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PFS-16/016', 'mr', 'मला इतकी थकवा येते की मी जिथे कुठे आहे तिथे झोपी जाऊ इच्छितो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/001', 'hi', 'पिछले महीने के दौरान, आप आम तौर पर रात को किस समय सोने जाते हैं?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/001', 'mr', 'गेल्या महिन्यात, तुम्ही रात्री साधारणपणे कधी झोपायला जाता?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/002', 'hi', 'पिछले महीने के दौरान, आपको हर रात सोने में आम तौर पर कितना समय (मिनटों में) लगा है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/002', 'mr', 'गेल्या महिन्यात, तुम्हाला दर रात्री झोपी जाण्यासाठी किती वेळ लागला (मिनिटांमध्ये)?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/003', 'hi', 'पिछले महीने के दौरान, आप आम तौर पर सुबह किस समय उठते हैं?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/003', 'mr', 'गेल्या महिन्यात, तुम्ही सकाळी नेहमी कोणत्या वेळी उठता?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/004', 'hi', 'पिछले महीने में, आपको रात में कितने घंटे वास्तविक नींद आई?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('PSQI/004', 'mr', 'गेल्या महिन्यात, रात्री तुम्हाला किती तासांची वास्तविक झोप मिळाली?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001', 'hi', 'जी.ए.आई.टी. प्रबन्ध को (१) एक सुरक्षित दूरी पर समानांतर चलने के लिए कहा जाता है एक दीवार सहित आधा मोड़ (आगे मुड़कर सामना करने के लिए) (चलने की विपरीत दिशा) और (२) एक साथ चलने के लिए बिना सहारे के (हील्स टोज तक)।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001', 'mr', 'जीएआयटी प्रॉडबल्डला (१) सुरक्षित अंतरावर समांतर चालण्यास सांगितले जाते. भिंतः अर्ध-वाग (वाग म्हणजे वळण) चालण्याच्या विरुद्ध दिशेने) आणि (२) एकत्र चालण्यासाठी. (पायाची टाच पायाच्या बोटांच्या) आधारविना.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/002', 'hi', 'स्टांस प्रोबैंड को प्राकृतिक स्थिति में (१) खड़े होने, (२) के साथ खड़े होने के लिए कहा जाता है एक साथ पैर समानांतर में (बड़े पैर की उंगलियां एक-दूसरे को छू रही) और (३) एक साथ (दोनों पैर एक पंक्ति पर, बीच में कोई जगह नहीं) एड़ी और अंगूठा)। प्रबन्धक जूते नहीं पहनता, आँखें खुला हुआ। प्रत्येक स्थिति के लिए तीन परीक्षण किए जाते हैं। सर्वश्रेष्ठ परीक्षण का मूल्यांकन किया जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/002', 'mr', 'स्टँस प्रोबँडला नैसर्गिक स्थितीत (१) उभे राहण्यास सांगितले जाते, (२) आणि पायांची एकसमान लांबी (मोठ्या बोटाची एकमेकांना स्पर्श होणे) (३) समवेत (दोन्ही पाय एकाच ओळीत, दरम्यान जागा नाही) टाच आणि बोटाचा). प्रबन्द शूज घालत नाही, डोळे खुला. प्रत्येक स्थितीसाठी, तीन चाचण्या करण्याची परवानगी आहे. सर्वोत्तम चाचणीचे मूल्यांकन केले जाते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/003', 'hi', 'प्रबन्धक को बिना बताए परीक्षा के लिए ले जाया जाता है। पैरों का सहारा लेना, आँखें खुली और बाहें बाहर फैलाए अग्रभाग।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/003', 'mr', 'एस.आय.टी.टी.इंग प्रोबँडला परीक्षेच्या पलंगावर बसण्यास सांगितले जाते. पायांचे आधार, डोळे उघडे आणि हात बाहेर पसरलेले पुढचा भाग.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/004', 'hi', 'वाक् विकार: सामान्य बातचीत के दौरान वाक् विकार का आकलन किया जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/004', 'mr', 'SPEECH DISTURBANCE: सामान्य संभाषणादरम्यान भाषण मोजले जाते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/005', 'hi', 'फिंगर चेज़ प्रत्येक पक्ष के लिए अलग से मूल्यांकित रोगी आराम से बैठता है (बाएँ)। यदि आवश्यक हो, तो पैरों का सहारा और धड़ ले जाने की अनुमति है। परीक्षक रोगी के सामने बैठता है और लगातार ५ बार अचानक और तेजी से इशारा करता है अनियंत्रित दिशाओं में एक अग्र तल में गति, लगभग ५० % तक प्रबलता तक पहुँचता है। आंदोलनों में होते हैं ३० से.मी. का आयाम और १ आवृत्ति हर २ सेकंड पर प्रबन्धक को आंदोलनों का पालन करने के लिए कहा जाता है अपनी तर्जनी से, यथासंभव तेजी और सटीकता से। पिछले ३ आंदोलनों के औसत प्रदर्शन को मूल्यांकित किया जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/005', 'mr', 'फिंगर चेस - प्रत्येक बाजूसाठी स्वतंत्रपणे मूल्यांकन प्रोबँड आरामात(डावीकडे) बसलेला असतो. आवश्यक असल्यास, पायांचे आधार आणि पाठीचा कणा बांधता येतो. परीक्षक पीडितेच्या समोर बसतो. आणि सलग ५ वेळा अचानक आणि जलद बिंदू करतो. पुढच्या पृष्ठभागावर अप्रत्याशित दिशांमध्ये हालचाली, सुमारे ५० % पर्यंत प्रयोजकाच्या पोहोचते. चळवळींमध्ये असतात ३० से.मी. चा विस्तार आणि १ हालचालीची वारंवारता दर दोन सेकंदांनी प्रबन्दला हालचालींचे अनुसरण करण्यास सांगितले जाते. त्याच्या तर्जनीने, शक्य तितक्या जलद आणि अचूकपणे. गेल्या ३ हालचालींचे सरासरी कामगिरीचे मूल्यांकन केले जाते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/006', 'hi', 'फिंगर चेज़ प्रत्येक पक्ष के लिए अलग से मूल्यांकित प्रबलित व्यक्ति आराम से बैठता है (दाहिने)। यदि आवश्यक हो, तो पैरों का सहारा और धड़ ले जाने की अनुमति है। परीक्षक रोगी के सामने बैठता है और लगातार ५ बार अचानक और तेजी से इशारा करता है अनियंत्रित दिशाओं में एक अग्र तल में गति, लगभग ५० % तक प्रबलता तक पहुँचता है। आंदोलनों में होते हैं ३० से.मी. का आयाम और १ आवृत्ति हर २ सेकंड पर प्रबन्धक को आंदोलनों का पालन करने के लिए कहा जाता है अपनी तर्जनी से, यथासंभव तेजी और सटीकता से। पिछले ३ आंदोलनों के औसत प्रदर्शन को मूल्यांकित किया जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/006', 'mr', 'फिंगर चेस - प्रत्येक बाजूसाठी स्वतंत्रपणे मूल्यांकन प्रोबँड आरामात बसलेला असतो. आवश्यक असल्यास, पायांचे आधार आणि पाठीचा कणा बांधता येतो. परीक्षक पीडितेच्या समोर बसतो आणि सलग ५ वेळा अचानक आणि जलद बिंदू करतो. पुढच्या पृष्ठभागावर अप्रत्याशित दिशांमध्ये हालचाली, सुमारे ५० % पर्यंत प्रापकपर्यंत पोहोचते. चळवळींमध्ये असतात ३० से.मी. चा विस्तार आणि १ हालचालीची वारंवारता दर दोन सेकंदांनी प्रबन्दला हालचालींचे अनुसरण करण्यास सांगितले जाते. त्याच्या तर्जनीने, शक्य तितक्या जलद आणि अचूकपणे. गेल्या ३ हालचालींचे सरासरी कामगिरीचे मूल्यांकन केले जाते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/007', 'hi', 'नाक-अंगुली परीक्षण प्रत्येक पक्ष के लिए अलग से मूल्यांकन किया जाता है रोगी आराम से बैठता है (बाएँ)। यदि आवश्यक हो, तो पैरों का सहारा और धड़ ले जाने की अनुमति है। प्रबन्धक को बार-बार इंगित करने के लिए कहा जाता है अपनी तर्जनी उंगली से नाक से परीक्षक की उंगली तक जो रोगी के सामने लगभग ९० प्रतिशत पर है प्रबलता। गतिविधियाँ मध्यम गति से की जाती हैं गति आंदोलनों का औसत प्रदर्शन मूल्यांकित किया जाता है। गतिज झटके के आयाम के अनुसार।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/007', 'mr', 'नाकाच्या बोटाची चाचणी - प्रत्येक बाजूसाठी स्वतंत्रपणे मूल्यांकन प्रोबँड आरामात(डावीकडे) बसलेला असतो. आवश्यक असल्यास, पायांचे आधार आणि पाठीचा कणा बांधता येतो. प्रबन्दला वारंवार निर्देश करण्यास सांगितले जाते त्याच्या नाकापासून परीक्षकाच्या बोटापर्यंत त्याच्या तर्जनीने जो सुमारे ९० % प्रकरणाच्या समोर आहे रुग्णांच्या समजुतीनुसार. हालचाली मध्यम गतीने केल्या जातात. वेग. हालचालींच्या सरासरी कामगिरीचे मूल्यांकन केले जाते. गतिज भूकंपाच्या विस्तारानुसार.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/008', 'hi', 'नाक-अंगुली परीक्षण प्रत्येक पक्ष के लिए अलग से मूल्यांकन किया जाता है प्रबलित रोगी आराम से बैठता है (दाहिने)। यदि आवश्यक हो, तो पैरों का सहारा और धड़ ले जाने की अनुमति है। प्रबन्धक को बार-बार इंगित करने के लिए कहा जाता है अपनी तर्जनी उंगली से नाक से परीक्षक की उंगली तक जो रोगी के सामने लगभग ९० प्रतिशत पर है प्रबलक की पहुँच। गतिविधियाँ मध्यम गति से की जाती हैं गति आंदोलनों का औसत प्रदर्शन मूल्यांकित किया जाता है। गतिज झटके के आयाम के अनुसार।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/008', 'mr', 'नाकाच्या बोटाची चाचणी - प्रत्येक बाजूसाठी स्वतंत्रपणे मूल्यांकन प्रोबँड आरामात बसलेला असतो. आवश्यक असल्यास, पायांचे आधार आणि पाठीचा कणा बांधता येतो. प्रबन्धला वारंवार निर्देश करण्यास सांगितले जाते त्याच्या नाकापासून परीक्षकाच्या बोटापर्यंत त्याच्या तर्जनीने जो सुमारे ९० % वर प्रात्यक्षिक व्यक्तीच्या समोर आहे प्रबन्धकाच्या व्याप्ती. हालचाली मध्यम गतीने केल्या जातात. वेग. हालचालींच्या सरासरी कामगिरीचे मूल्यांकन केले जाते. गतिज भूकंपाच्या विस्तारानुसार.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/009', 'hi', 'फास्ट ऑल्टरनेटिंग हैंड मूवमेंट्स प्रत्येक पक्ष के लिए अलग से मूल्यांकित की जाती हैं। रोगी आराम से बैठता है (बाएँ)। यदि आवश्यक हो, तो पैरों का सहारा और धड़ ले जाने की अनुमति है। प्रबन्धक को १० करने के लिए कहा जाता है चक्र: दोहरावदार वैकल्पिक घुमाव और अधो घुमाव हाथ को उसके जांघ पर जितनी जल्दी और सटीक हो सके उतनी जल्दी संभव। गति परीक्षक द्वारा एक पर प्रदर्शित की जाती है। गति: ७ सेकंड के भीतर १० चक्र। सटीक समय के लिए आंदोलन निष्पादन को ध्यान में रखना होगा।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/009', 'mr', 'जलद पर्यायी हातांच्या हालचाली प्रत्येक बाजूसाठी स्वतंत्रपणे मूल्यांकित केल्या जातात. प्रोबँड आरामात(डावीकडे) बसलेला असतो. आवश्यक असल्यास, पायांचे आधार आणि पाठीचा कणा बांधता येतो. प्रबन्दला १० करायला सांगितले जाते. चक्र: आवर्तन हाताने त्याच्या/तिच्या मांडीवर झटकन आणि अचूकपणे शक्य. परीक्षक हालचाली दर्शवतो. अंदाजे वेग ७ सेकंदात १० फेऱ्या. नेमके वेळा हालचालींची अंमलबजावणी करावी लागते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/010', 'hi', 'फास्ट ऑल्टरनेटिंग हैंड मूवमेंट्स प्रत्येक पक्ष के लिए अलग से मूल्यांकित की जाती हैं। प्रबलित रोगी आराम से बैठता है (दाहिने)। यदि आवश्यक हो, तो पैरों का सहारा और धड़ ले जाने की अनुमति है। प्रबन्धक को १० करने के लिए कहा जाता है चक्र: दोहरावदार वैकल्पिक घुमाव और अधो घुमाव हाथ को उसके जांघ पर जितनी जल्दी और सटीक हो सके उतनी जल्दी संभव। गति परीक्षक द्वारा एक पर प्रदर्शित की जाती है। गति: लगभग ७ सेकंड के भीतर १० चक्र। सटीक समय के लिए आंदोलन निष्पादन को ध्यान में रखना होगा।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/010', 'mr', 'जलद पर्यायी हातांच्या हालचाली प्रत्येक बाजूसाठी स्वतंत्रपणे मूल्यांकित केल्या जातात. प्रोबँड आरामात बसलेला असतो. आवश्यक असल्यास, पायांचे आधार आणि पाठीचा कणा बांधता येतो. प्रबन्दला १० करायला सांगितले जाते. चक्र: आवर्तन हाताने त्याच्या/तिच्या मांडीवर झटकन आणि अचूकपणे शक्य. परीक्षक हालचाली दर्शवतो. अंदाजे वेग ७ सेकंदात १० फेऱ्या. नेमके वेळा हालचालींची अंमलबजावणी करावी लागते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/011', 'hi', 'एड़ी-टखनी स्लाइड को प्रत्येक पक्ष (बाएँ) के लिए अलग से मूल्यांकित किया जाता है। प्रबन्धक परीक्षा-बेड पर लेटा हुआ है, उसकी दृष्टि से दूर पैर। प्रबन्धक से एक पैर उठाने और एड़ी की ओर इशारा करने के लिए कहा जाता है विपरीत घुटने तक, टांग के साथ नीचे की ओर टखने को झुकाएं और पैर को परीक्षा टेबल पर वापस रखें। यह कार्य तीन बार किया जाता है। स्लाइड-डाउन की गतिविधियाँ एक सेकंड के भीतर प्रदर्शित किया जाएगा। यदि वारिस बिना तीनों परीक्षणों में संपर्क करने पर टखने के निचले हिस्से में ४ का मूल्यांकन मिला।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/011', 'mr', 'हिल्-शिन स्लाइडला प्रत्येक बाजूसाठी (डावीकडे) स्वतंत्रपणे मूल्यांकन दिले जाते. प्रबन्द परीक्षेसाठी पलंगावर पडला होता, त्याला दृष्टी नव्हती. पाय. प्रबन्धला एक पाय वर उचलण्यास सांगितले जाते, टाचेने दाखवायला सांगितले जाते. विरुद्ध गुडघ्यापर्यंत, मांडीच्या खालच्या बाजूस खाली सरकून गुडघा वाकवून पाय परीक्षणाच्या पलंगावर ठेवा. हा कार्य तीन वेळा केले जाते. खाली सरकताना एक सेकंदात सादर करावे लागेल. जर तीनही चाचण्यांमध्ये, शिनच्या संपर्कस्थानी ४ गुण दिले.', '2026-07-13T08:34:09.787168+00:00'::timestamptz)
) AS v(id, lang, txt, ts)
