  ('THI/017', 'hi', 'क्या आपको लगता है कि आपकी टिनिटस की समस्या ने आपके परिवार और दोस्तों के साथ आपके संबंधों पर तनाव डाला है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/017', 'mr', 'तुम्हाला असे वाटते का की तुमच्या टिनिटसच्या समस्येमुळे तुमच्या कुटुंबातील सदस्य आणि मित्रमंडळींशी असलेले नाते ताणले गेले आहे?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/018', 'hi', 'क्या आपको अपने टिनिटस से ध्यान हटाकर अन्य चीजों पर ध्यान केंद्रित करना मुश्किल लगता है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/018', 'mr', 'तुम्हाला तुमच्या कर्णनादापासून तुमचे लक्ष दूर करून इतर गोष्टींवर लक्ष केंद्रित करणे कठीण वाटते का?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/019', 'hi', 'क्या आपको ऐसा लगता है कि आपके टिनिटस पर आपका कोई नियंत्रण नहीं है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/019', 'mr', 'तुम्हाला असे वाटते का की तुमच्या टिनिटसवर तुमचे कोणतेही नियंत्रण नाही?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/020', 'hi', 'आपके कर्णक्ष्वेण के कारण, क्या आप अक्सर थके हुए महसूस करते हैं?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/020', 'mr', 'तुमच्या टिटनीटसच्या कारणाने तुम्हाला अनेकदा थकवा जाणवतो का?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/021', 'hi', 'आपके टिनिटस के कारण, क्या आप उदास महसूस करते हैं?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/021', 'mr', 'तुमच्या टिटनीटसच्या कारणाने तुम्हाला नैराश्य येते का?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/022', 'hi', 'क्या आपको अपने टिनिटस के कारण चिंता होती है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/022', 'mr', 'तुमच्या टिनिटसमुळे तुम्हाला चिंता वाटते का?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/023', 'hi', 'क्या आपको लगता है कि आप अब अपने टिनिटस से निपट नहीं सकते हैं?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/023', 'mr', 'तुम्हाला असे वाटते का की आता तुम्ही तुमच्या टिनिटसशी जुळवून घेऊ शकत नाही?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/024', 'hi', 'क्या तनाव में होने पर आपका कर्णक्ष्वेण बदतर हो जाता है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/024', 'mr', 'ताणतणावामुळे तुमचा कर्णघात अधिक तीव्र होतो का?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/025', 'hi', 'क्या आपका कर्णक्ष्वेण आपको असुरक्षित महसूस कराता है?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('THI/025', 'mr', 'तुमचा टिनिटस तुम्हाला असुरक्षित वाटतो का?', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VAS/001', 'hi', '० से १० तक के पैमाने पर अपना दर्द दर्ज करें, जहाँ ० का अर्थ है कोई दर्द नहीं और १० का अर्थ है गंभीर दर्द।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VAS/001', 'mr', '० म्हणजे अजिबात वेदना नसणे ते १० म्हणजे तीव्र वेदना असे वेदनांचे प्रमाण लिहा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/001', 'hi', 'सुपरमार्केट के गलियारे में चलते समय आपको चक्कर आने की मात्रा बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/001', 'mr', 'सुपरमार्केटच्या कप्प्यातून चालत असताना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/002', 'hi', 'कार में यात्री होने पर आपको कितना चक्कर आता है, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/002', 'mr', 'गाडी चालवताना तुम्हाला किती चक्कर येते ते सांगा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/003', 'hi', 'फ्लोरोसेंट लाइट के नीचे होने पर आपको कितना चक्कर आता है, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/003', 'mr', 'फ्लोरोसेंट दिव्यांच्या प्रकाशात असताना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/004', 'hi', 'व्यस्त चौराहे पर यातायात देखते समय आपको कितना चक्कर आता है, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/004', 'mr', 'गर्दीच्या चौकात वाहतूक कोंडी पाहतांना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/005', 'hi', 'शॉपिंग मॉल में चलते समय आपको कितना चक्कर आता है, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/005', 'mr', 'खरेदी मॉलमध्ये फिरताना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/006', 'hi', 'ईस्कलेटर से नीचे जाते समय आपको कितना चक्कर आता है, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/006', 'mr', 'एस्केलेटर खाली जात असताना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/007', 'hi', 'फिल्म थिएटर में फिल्म देखते समय आपको चक्कर कितनी आती हैं, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/007', 'mr', 'चित्रपटगृहात चित्रपट पाहताना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/008', 'hi', 'एक पैटर्न वाले फर्श पर चलते समय आपको कितना चक्कर आता है, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/008', 'mr', 'नक्षीदार फरशा वरून चालताना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/009', 'hi', 'एक्शन वाली टेलीविजन कार्यक्रम देखते समय आपको कितना चक्कर आता है, यह बताइए।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('VVAS/009', 'mr', 'दूरचित्रवाणीवर युद्धाचे दृश्य पाहताना तुम्हाला किती चक्कर येते ते सूचित करा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz)
