INSERT INTO reference.prs_option_translations (option_id, language_code, option_label, created_at)
SELECT v.id, v.lang, v.txt, v.ts
FROM (VALUES
  ('DN-4/009/02', 'hi', 'हाँ', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DN-4/009/02', 'mr', 'होय', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DN-4/010/01', 'hi', 'नहीं', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DN-4/010/01', 'mr', 'नाही', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DN-4/010/02', 'hi', 'हाँ', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DN-4/010/02', 'mr', 'होय', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/01', 'hi', 'सामान्य स्मृति.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/01', 'mr', 'सामान्य स्मृती.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/02', 'hi', 'कभी-कभी वे बातें भूल जाते हैं जो उन्हें हाल ही में बताई गई थीं। इससे ज्यादा दिक्कत नहीं होती.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/02', 'mr', 'कधीकधी त्यांना अलीकडे सांगितलेल्या गोष्टी विसरतात. त्यामुळे फारशा समस्या येत नाहीत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/03', 'hi', 'हल्की लगातार भूलने की बीमारी. हाल की घटनाओं को याद रखता है लेकिन अक्सर कुछ हिस्सों को भूल जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/03', 'mr', 'सौम्य सातत्यपूर्ण विस्मरण. अलीकडील घटना आठवते परंतु अनेकदा काही भाग विसरते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/04', 'hi', 'मध्यम स्मृति हानि. हाल की घटनाओं के लिए यह और भी बुरा है। हो सकता है कि आपको अभी-अभी उन्हें बताई गई कोई बात याद न हो। रोजमर्रा के कार्यों में समस्या उत्पन्न करता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/04', 'mr', 'मध्यम स्मृती कमी होणे. अलीकडील घटनांसाठी अधिक वाईट. तुम्ही त्यांना जे सांगितले ते त्यांना कदाचित आठवत नसेल. दैनंदिन कामांमध्ये समस्या निर्माण करतात.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/05', 'hi', 'पर्याप्त स्मृति हानि. हाल की या नई सीखी गई बातों को जल्दी भूल जाता है। वे केवल उन्हीं चीज़ों को याद रख सकते हैं जिन्हें वे लंबे समय से जानते हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/05', 'mr', 'स्मरणशक्तीमध्ये लक्षणीय घट. अलीकडच्या किंवा नव्याने शिकलेल्या गोष्टी लवकर विसरतो. ते फक्त त्यांना बऱ्याच काळापासून माहित असलेल्या गोष्टी आठवू शकतात.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/06', 'hi', 'बुनियादी तथ्य जैसे सप्ताह का दिन, आखिरी भोजन कब खाया या अगला भोजन क्या होगा, याद नहीं रहता।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/06', 'mr', 'आठवड्याचा दिवस, शेवटचे जेवण केव्हा झाले किंवा पुढील जेवण काय असेल यासारख्या मूलभूत गोष्टी आठवणार नाहीत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/07', 'hi', 'सबसे बुनियादी चीजें भी याद नहीं रहतीं.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/001/07', 'mr', 'अगदी मूलभूत गोष्टीही आठवत नाहीत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/01', 'hi', 'बात करने और दूसरों को समझने की सामान्य क्षमता।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/01', 'mr', 'बोलण्याची आणि इतरांना समजून घेण्याची सामान्य क्षमता.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/02', 'hi', 'कभी-कभी कोई शब्द नहीं मिल पाता, लेकिन बातचीत जारी रखने में सक्षम होता हूं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/02', 'mr', 'कधीकधी एखादा शब्द सापडत नाही, परंतु तरीही संभाषण चालू ठेवता येते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/03', 'hi', 'अक्सर शब्द भूल जाते हैं. इसके स्थान पर गलत शब्द का प्रयोग हो सकता है। कुछ लोगों को विचार व्यक्त करने और उत्तर देने में परेशानी होती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/03', 'mr', 'अनेकदा शब्द विसरतो. चुकीचा शब्द त्याच्या जागी वापरणे शक्य आहे. विचार व्यक्त करण्यात आणि उत्तरे देण्यात काही अडचणी.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/04', 'hi', 'आमतौर पर वाक्यों का उपयोग करके प्रश्नों का उत्तर देता है लेकिन शायद ही कभी बातचीत शुरू होती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/04', 'mr', 'सहसा वाक्यांचा वापर करून प्रश्नांची उत्तरे देतो परंतु क्वचितच संभाषण सुरू करतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/05', 'hi', 'सवालों के जवाब देता है, लेकिन जवाबों को समझना अक्सर मुश्किल होता है या समझ में नहीं आता। आमतौर पर सरल निर्देशों का पालन करने में सक्षम।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/05', 'mr', 'ते प्रश्नांची उत्तरे देतात, परंतु प्रतिसाद समजून घेणे कठीण असते किंवा त्याचा अर्थ कळत नाही. सहसा सोप्या सूचनांचे पालन करू शकतात.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/06', 'hi', 'वाणी का प्रायः कोई अर्थ नहीं होता। प्रश्नों का उत्तर नहीं दे सकते या निर्देशों का पालन नहीं कर सकते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/06', 'mr', 'भाषण अनेकदा अर्थपूर्ण नसते. प्रश्नांची उत्तरे देऊ शकत नाही किंवा सूचनांचे पालन करू शकत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/07', 'hi', 'अधिकांश समय प्रतिक्रिया नहीं देता.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/002/07', 'mr', 'बहुतेक वेळा प्रतिसाद देत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/01', 'hi', 'सामान्य - लोगों को पहचानता है और आम तौर पर जानता है कि वे कौन हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/01', 'mr', 'सामान्य - लोकांना ओळखते आणि सामान्यतः ते कोण आहेत हे जाणते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/02', 'hi', 'आमतौर पर पोते-पोतियों, चचेरे भाई-बहनों या रिश्तेदारों को पहचानता है, जिन्हें अक्सर देखा नहीं जाता है, लेकिन उन्हें याद नहीं होता कि वे कैसे संबंधित हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/02', 'mr', 'सहसा नातवंडे, चुलत भाऊ किंवा चुलत बहिणींना ओळखते, परंतु ते वारंवार भेटत नसले तरी ते कसे संबंधित आहेत हे त्यांना आठवत नसेल.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/03', 'hi', 'आमतौर पर परिवार के उन सदस्यों को नहीं पहचानता, जिन्हें बार-बार नहीं देखा जाता है। अक्सर इस बात को लेकर असमंजस रहता है कि परिवार के सदस्य जैसे पोते-पोतियां, भतीजियां या भतीजे उनसे कैसे संबंधित हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/03', 'mr', 'सहसा वारंवार न दिसणाऱ्या कुटुंबातील सदस्यांना ओळखत नाही. नातवंडे, भाची किंवा भाचे यांसारख्या कौटुंबिक सदस्यांशी त्यांचे संबंध कसे आहेत याबद्दल अनेकदा गोंधळ होतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/04', 'hi', 'कभी-कभी परिवार के करीबी सदस्यों या अन्य लोगों को नहीं पहचान पाता जिनसे वह बार-बार मिलता है। वे अपने बच्चों, भाइयों या बहनों को नहीं पहचान सकते, जिन्हें नियमित आधार पर नहीं देखा जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/04', 'mr', 'कधीकधी ते जवळच्या कुटुंबातील सदस्यांना किंवा ते वारंवार पाहतात अशा इतरांना ओळखत नाहीत. नियमितपणे न दिसणाऱ्या त्यांच्या मुला-मुलींना, भावांना किंवा बहिणींना ते ओळखू शकणार नाहीत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/05', 'hi', 'अक्सर जीवनसाथी या देखभाल करने वाले को नहीं पहचानता।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/05', 'mr', 'वारंवार जोडीदार किंवा काळजी घेणाऱ्याला ओळखत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/06', 'hi', 'दूसरों की उपस्थिति की कोई पहचान या जागरूकता नहीं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/003/06', 'mr', 'इतरांच्या उपस्थितीची कोणतीही ओळख किंवा जाणीव नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/01', 'hi', 'दिन के समय और सप्ताह के दिन के बारे में सामान्य जागरूकता।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/01', 'mr', 'दिवसाची आणि दिवसाच्या आठवड्याची सामान्य जाणीव.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/02', 'hi', 'इस बारे में कुछ भ्रम है कि यह कौन सा समय है या सप्ताह का कौन सा दिन है, लेकिन इतना गंभीर नहीं कि रोजमर्रा की गतिविधियों में हस्तक्षेप हो।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/02', 'mr', 'काय वेळ आहे किंवा आठवड्याचा कोणता दिवस आहे याबद्दल काही गोंधळ, परंतु दैनंदिन क्रियाकलापांमध्ये हस्तक्षेप करण्यासाठी पुरेसा गंभीर नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/03', 'hi', 'दिन के समय को लेकर अक्सर भ्रमित रहते हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/03', 'mr', 'दिवसाच्या वेळेबद्दल वारंवार गोंधळ होतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/04', 'hi', 'दिन के समय को लेकर लगभग हमेशा भ्रमित रहते हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/04', 'mr', 'जवळजवळ नेहमीच दिवसाच्या वेळेबद्दल गोंधळलेला असतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/05', 'hi', 'समय का बिल्कुल पता नहीं लगता.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/004/05', 'mr', 'वेळ कळत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/01', 'hi', 'नई जगहों पर भी वे कहां हैं, इसकी सामान्य जागरूकता।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/01', 'mr', 'नवीन ठिकाणी ते कुठे आहेत याची सामान्य जाणीव.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/02', 'hi', 'कभी-कभी नई जगहों पर भटकाव हो जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/02', 'mr', 'कधीकधी नवीन ठिकाणी दिशाभूल होते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/03', 'hi', 'नई जगहों पर बार-बार भटकाव होना।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/03', 'mr', 'वारंवार नवीन ठिकाणी दिशाभूल होणे.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/04', 'hi', 'आम तौर पर परिचित स्थानों में भी, भटका हुआ महसूस होता है। शायद भूल जाएं कि वे पहले से ही घर पर हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/04', 'mr', 'सहसा दिशाभूल झालेली, अगदी परिचित ठिकाणीही. ते आधीच घरी आले आहेत हे विसरून जा.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/05', 'hi', 'जगह को लेकर लगभग हमेशा असमंजस में रहते हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/005/05', 'mr', 'जवळजवळ नेहमीच स्थानाबद्दल गोंधळलेला असतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/01', 'hi', 'सामान्य - पहले की तरह निर्णय लेने में सक्षम।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/01', 'mr', 'सामान्य - पूर्वीप्रमाणे निर्णय घेण्यास सक्षम.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/02', 'hi', 'केवल दैनिक जीवन में निर्णय लेने में कुछ कठिनाई उत्पन्न होती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/02', 'mr', 'दैनंदिन जीवनात उद्भवणाऱ्या निर्णयांमध्ये केवळ काही अडचणी येतात.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/03', 'hi', 'मध्यम कठिनाई. जब चीजें जटिल हो जाती हैं या योजनाएं बदल जाती हैं तो भ्रमित हो जाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/03', 'mr', 'मध्यम कठीणता. जेव्हा गोष्टी गुंतागुंतीच्या होतात किंवा योजना बदलतात तेव्हा गोंधळ होतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/04', 'hi', 'शायद ही कभी कोई महत्वपूर्ण निर्णय लेता है। आसानी से भ्रमित हो जाता है.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/04', 'mr', 'क्वचितच कोणतेही महत्त्वपूर्ण निर्णय घेतो. सहजच गोंधळते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/05', 'hi', 'अधिकांश समय समझ नहीं आता कि क्या हो रहा है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/006/05', 'mr', 'बहुतेक वेळा काय चालले आहे हे समजू शकत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/01', 'hi', 'सामान्य - लोगों के साथ पहले जैसा ही व्यवहार करता है', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/01', 'mr', 'सामान्य - लोकांबरोबर पूर्वीप्रमाणेच वागते', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/02', 'hi', 'केवल हल्की समस्याएं जो वास्तव में महत्वपूर्ण नहीं हैं, लेकिन स्पष्ट रूप से पिछले वर्षों की तुलना में अलग तरह से काम करती हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/02', 'mr', 'फक्त सौम्य समस्या ज्या खरोखर महत्त्वाच्या नाहीत, परंतु मागील वर्षांपेक्षा स्पष्टपणे वेगळ्या प्रकारे कार्य करतात.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/03', 'hi', 'बिना सहायता के भी सामुदायिक गतिविधियों में भाग ले सकते हैं। जो लोग उन्हें नहीं जानते उन्हें यह सामान्य लग सकता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/03', 'mr', 'तरीही मदतीशिवाय सामुदायिक कार्यांमध्ये सहभागी होऊ शकते. जे लोक त्यांना ओळखत नाहीत त्यांना हे सामान्य दिसू शकते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/04', 'hi', 'देखभाल करने वाले की मदद के बिना अक्सर घर से बाहर के लोगों से निपटने में परेशानी होती है। आमतौर पर दोस्तों के साथ शांत घरेलू गतिविधियों में भाग ले सकते हैं। जो कोई भी उन्हें देखता है उसे समस्या स्पष्ट हो जाती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/04', 'mr', 'बऱ्याचदा काळजी घेणाऱ्याच्या मदतीशिवाय घराबाहेरील लोकांशी व्यवहार करण्यात त्रास होतो. सहसा मित्रांसोबत शांत घरगुती कामांमध्ये सहभागी होऊ शकतो. ती समस्या त्यांना पाहणाऱ्या कोणालाही स्पष्ट दिसते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/05', 'hi', 'अब वह घर पर अन्य लोगों को शामिल करने वाली गतिविधियों में किसी भी वास्तविक तरीके से भाग नहीं लेता है। केवल प्राथमिक देखभालकर्ता के साथ ही व्यवहार कर सकता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/05', 'mr', 'इतर लोकांशी संबंधित घरगुती उपक्रमांमध्ये आता कोणतीही प्रत्यक्ष भूमिका घेत नाही. केवळ प्राथमिक काळजी घेणाऱ्या व्यक्तीशीच व्यवहार करता येतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/06', 'hi', 'प्राथमिक देखभालकर्ता तक भी बहुत कम या कोई प्रतिक्रिया नहीं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/007/06', 'mr', 'प्राथमिक काळजी घेणाऱ्याला अगदी थोडा किंवा अजिबात प्रतिसाद मिळत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/01', 'hi', 'सामान्य। घर के काम करने की क्षमता में कोई कमी नहीं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/01', 'mr', 'सामान्य. घरातल्या गोष्टी करण्याची क्षमता कमी झालेली नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/02', 'hi', 'घरेलू गतिविधियों में कुछ समस्याएँ। धन प्रबंधन (बिलों का भुगतान) और चीजों को ठीक करने में अधिक परेशानी हो सकती है। अभी भी किसी स्टोर पर जा सकते हैं, खाना बना सकते हैं या साफ़-सफ़ाई कर सकते हैं। अभी भी दिलचस्पी और समझ के साथ टीवी देखता है या अखबार पढ़ता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/02', 'mr', 'गृह कार्यांसंबंधी काही समस्या. पैशाच्या व्यवस्थापनात (देयके भरणे) आणि गोष्टी दुरुस्त करण्यात अधिक अडचणी येऊ शकतात. तरीही दुकानात जाऊ शकता, स्वयंपाक करू शकता किंवा स्वच्छता करू शकता. तरीही टीव्ही बघतो किंवा वर्तमानपत्र वाचतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/03', 'hi', 'दुकान पर जाना, खाना बनाना या सफाई करना जैसे आसान कामों में गलतियाँ करता है। अखबार, टीवी या रेडियो में रुचि कम होना। अक्सर किसी एक विषय पर लंबी बातचीत नहीं हो पाती।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/03', 'mr', 'दुकानात जाणे, स्वयंपाक करणे किंवा स्वच्छता करणे यासारख्या सोप्या कामांमध्ये तो चुका करतो. वृत्तपत्र, दूरदर्शन किंवा आकाशवाणीमध्ये रस कमी होणे. अनेकदा एकाच विषयावरील दीर्घ संभाषण अनुसरू शकत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/04', 'hi', 'बहुत अधिक मदद के बिना खरीदारी करने, खाना पकाने या साफ़-सफ़ाई करने में सक्षम नहीं। अखबार या टीवी समझ नहीं आता. बातचीत का अनुसरण नहीं किया जा सकता.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/04', 'mr', 'खूप मदतीशिवाय खरेदी, स्वयंपाक किंवा स्वच्छता करू शकत नाही. त्याला वृत्तपत्र किंवा दूरदर्शन समजत नाही. संभाषण अनुसरणे शक्य झाले नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/05', 'hi', 'अब कोई भी घर-आधारित गतिविधियाँ नहीं करता।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/008/05', 'mr', 'नाहीतर घरगुती उपक्रम आता नाहीत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/01', 'hi', 'सामान्य। खुद का उतना ही ख्याल रखते हैं जितना पहले रखते थे।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/01', 'mr', 'सामान्य. ते स्वतः तसेच त्यांची काळजी घेत असत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/02', 'hi', 'कभी-कभी बाल धोना, दाढ़ी बनाना, कंघी करना भूल जाता है या गलत प्रकार के कपड़े पहनना भूल जाता है। उतने साफ-सुथरे नहीं, जितने पहले हुआ करते थे।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/02', 'mr', 'कधीकधी धुणे, दाढी करणे किंवा केस विंचरणे विसरतात किंवा चुकीचे कपडे घालतात. पूर्वीसारखे नीटनेटके नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/03', 'hi', 'कपड़े पहनने, धोने और व्यक्तिगत साज-सज्जा में मदद की आवश्यकता होती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/03', 'mr', 'कपडे घालणे, धुणे आणि वैयक्तिक सौंदर्यप्रसाधनांसाठी मदतीची आवश्यकता असते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/04', 'hi', 'व्यक्तिगत देखभाल के लिए पूरी तरह से मदद पर निर्भर।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/009/04', 'mr', 'वैयक्तिक काळजीसाठी पूर्णपणे मदतीवर अवलंबून आहे.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/01', 'hi', 'सामान्य तौर पर, उन्हें जो खाना परोसा जाता है उसे खाने में मदद की ज़रूरत नहीं होती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/01', 'mr', 'सामान्य, त्यांना वाढलेले अन्न खाण्यासाठी मदतीची आवश्यकता नसते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/02', 'hi', 'भोजन काटने में सहायता की आवश्यकता हो सकती है या कुछ खाद्य पदार्थों से परेशानी हो सकती है, लेकिन मूल रूप से स्वयं खाने में सक्षम हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/02', 'mr', 'कदाचित अन्नाचे काटा कापणे किंवा काही पदार्थ खाण्यात अडचण येऊ शकते, परंतु मूलतः एकटेच खाऊ शकते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/03', 'hi', 'आम तौर पर खुद को खिलाने में सक्षम लेकिन कुछ मदद की आवश्यकता हो सकती है। भोजन के दौरान रुचि कम हो सकती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/03', 'mr', 'सामान्यतः स्वतःहून खाऊ शकतात परंतु त्यांना काही मदतीची आवश्यकता असू शकते. जेवणाच्या वेळी कदाचित रस कमी झाला असेल.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/04', 'hi', 'खिलाने की जरूरत है. निगलने में परेशानी हो सकती है.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/010/04', 'mr', 'त्याला/तिला खायला द्यावे लागते. गिळण्यास त्रास होऊ शकतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/01', 'hi', 'सामान्य - शारीरिक समस्याओं को छोड़कर पेशाब या आंत्र को नियंत्रित करने में कोई समस्या नहीं होती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/01', 'mr', 'सामान्य - शारीरिक समस्या वगळता त्यांना लघवी किंवा मल नियंत्रित करण्यात समस्या येत नाहीत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/02', 'hi', 'पेशाब को नियंत्रित करने में शायद ही कभी विफल रहता है (आमतौर पर प्रति माह एक से भी कम दुर्घटना)।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/02', 'mr', 'मूत्रत्यागावर नियंत्रण ठेवण्यात क्वचितच अपयशी ठरते (सामान्यतः दर महिन्याला एक अपघात).', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/03', 'hi', 'पेशाब को नियंत्रित करने में कभी-कभी विफलता (लगभग सप्ताह में एक बार या उससे कम)।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/03', 'mr', 'लघवीवर नियंत्रण ठेवण्यात अधूनमधून अपयश (आठवड्यातून एकदा किंवा त्यापेक्षा कमी वेळा).', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/04', 'hi', 'बार-बार पेशाब को नियंत्रित करने में विफल रहता है (सप्ताह में एक बार से अधिक)।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/04', 'mr', 'वारंवार लघवीवर नियंत्रण ठेवण्यात अपयशी ठरते (आठवड्यातून एकदापेक्षा जास्त).', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/05', 'hi', 'आम तौर पर पेशाब को नियंत्रित करने में विफल रहता है और अक्सर आंतों को नियंत्रित नहीं कर पाता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/011/05', 'mr', 'सामान्यतः लघवीवर नियंत्रण ठेवण्यात अपयशी ठरते आणि वारंवार आतड्यांस नियंत्रित करू शकत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/01', 'hi', 'सामान्य, अपने आप घूमने-फिरने में सक्षम। (शारीरिक समस्याएं हो सकती हैं जिसके लिए छड़ी या वॉकर की आवश्यकता होती है)।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/01', 'mr', 'सामान्य, स्वत:च्या हातांनी फिरू शकणारे. (शारीरिक समस्या असू शकतात ज्यांना बेंत किंवा चालण्याच्या साहाय्याची आवश्यकता असते).', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/02', 'hi', 'कभी-कभी वाहन चलाते समय या सार्वजनिक परिवहन लेते समय भ्रमित हो जाता है, विशेषकर नई जगहों पर। अकेले स्थानों पर चलने में सक्षम।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/02', 'mr', 'कधीकधी गाडी चालवताना किंवा सार्वजनिक वाहतूक करताना, विशेषतः नवीन ठिकाणी गोंधळ होतो. एकट्याने ठिकाणी फिरता येते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/03', 'hi', 'परिचित स्थानों पर भी अकेले गाड़ी नहीं चला सकते या सार्वजनिक परिवहन नहीं ले सकते। थोड़ी दूर तक बाहर अकेले चल सकते हैं। घर से बहुत दूर चलने पर खो सकते हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/03', 'mr', 'एकट्याने वाहन चालवू शकत नाही किंवा सार्वजनिक वाहतूक करू शकत नाही, अगदी परिचित ठिकाणीही. थोड्या अंतरासाठी बाहेर एकटे चालू शकते का? घरापासून खूप दूर चाललो तर हरवून जाऊ शकतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/04', 'hi', 'बाहर अकेले नहीं छोड़ा जा सकता. बिना खोए या भ्रमित हुए घर के आसपास घूम सकते हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/04', 'mr', 'एकटं बाहेर राहू शकत नाही. हरवले किंवा गोंधळून न जाता घराभोवती फिरू शकते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/05', 'hi', 'भ्रमित हो जाते हैं और उन्हें घर के आसपास अपना रास्ता ढूंढने में मदद की ज़रूरत होती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/05', 'mr', 'गोंधळते आणि त्याला घरातून मार्ग शोधण्यात मदतीची गरज असते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/06', 'hi', 'लगभग हमेशा बिस्तर या कुर्सी पर। मदद से कुछ कदम चलने में सक्षम हो सकता है, लेकिन दिशा का ज्ञान नहीं है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/06', 'mr', 'जवळजवळ नेहमीच पलंगावर किंवा खुर्चीवर. कदाचित मदतीसह काही पावले चालू शकतील, परंतु त्यांना दिशेची जाणीव नसते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/07', 'hi', 'हमेशा बिस्तर पर. बैठने या खड़े होने में असमर्थ.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('DSRS/012/07', 'mr', 'नेहमी पलंगावर. बसू किंवा उभे राहू शकत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('EQ-5D-5L/001/01', 'hi', 'मुझे चलने-फिरने में कोई परेशानी नहीं होती', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
