  ('HDRS/003/03', 'hi', 'काश वह मर जाता/चाहती या स्वयं की संभावित मृत्यु का कोई विचार।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('HDRS/003/03', 'mr', 'इच्छा की तो/ती मरण पावला असो किंवा आत्महत्येचे काही विचार येत असावेत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
