  ('MADRS/006/05', 'hi', 'ध्यान केंद्रित करने और विचार बनाए रखने में कठिनाइयाँ जिससे पढ़ने या बातचीत करने की क्षमता कम हो जाती है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/006/05', 'mr', 'एकाग्रता आणि विचार टिकवून ठेवण्यात अडचणी ज्यामुळे वाचन किंवा संभाषण राखण्याची क्षमता कमी होते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
