  ('MADRS/007/03', 'hi', 'गतिविधियाँ शुरू करने में कठिनाइयाँ।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/007/03', 'mr', 'क्रियाकलाप सुरू करण्यात अडचणी.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
