  ('MADRS/007/04', 'mr', '३', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/007/05', 'hi', 'प्रयास से की जाने वाली सरल दिनचर्या की गतिविधियों को शुरू करने में कठिनाइयाँ।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/007/05', 'mr', 'सोप्या दिनचर्येच्या उपक्रमांना, जे प्रयत्नांसह केले जातात, सुरू करण्यात अडचणी.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/007/06', 'hi', '5', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
