  ('MADRS/007/07', 'hi', 'पूर्ण शिथिलता. बिना मदद के कुछ भी करने में असमर्थ.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/007/07', 'mr', 'पूर्ण आळस. मदतीशिवाय काहीही करू शकत नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/01', 'hi', 'परिवेश और अन्य लोगों में सामान्य रुचि।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/01', 'mr', 'सभोवतालात आणि इतर लोकांमध्ये सामान्य स्वारस्य.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/02', 'hi', '1', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/02', 'mr', '१', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/03', 'hi', 'सामान्य रुचियों का आनंद लेने की क्षमता कम हो गई।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/03', 'mr', 'नेहमीच्या आवडींचा आनंद घेण्याची क्षमता कमी होते.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/04', 'hi', '3', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/04', 'mr', '३', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/05', 'hi', 'परिवेश में रुचि की हानि. भावनाओं या दोस्तों और परिचितों की हानि।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/05', 'mr', 'सभोवतालच्या वातावरणात रस कमी होणे. भावना किंवा मित्र आणि ओळखीच्या गमावणे.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/06', 'hi', '5', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/06', 'mr', '५', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/07', 'hi', 'भावनात्मक रूप से पंगु होने का अनुभव, क्रोध, दुःख या खुशी महसूस करने में असमर्थता और करीबी रिश्तेदारों और दोस्तों के लिए महसूस करने में पूर्ण या यहां तक ​​कि दर्दनाक विफलता।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/008/07', 'mr', 'भावनिकदृष्ट्या पक्षाघात होणे, राग, दुःख किंवा आनंद जाणवण्यास असमर्थता आणि जवळच्या नातेवाईक आणि मित्रांसाठी भावना जाणवण्यात संपूर्ण किंवा वेदनादायक अपयश.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/01', 'hi', 'कोई निराशावादी विचार नहीं.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/01', 'mr', 'निराशावादी विचार नाहीत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/02', 'hi', '1', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/02', 'mr', '१', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/03', 'hi', 'विफलता, आत्म-निंदा या आत्म-ह्रास के उतार-चढ़ाव वाले विचार।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/03', 'mr', 'अपयशाचे चढ-उतार, आत्म-निंदा किंवा आत्म-अपमान.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/04', 'hi', '3', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/04', 'mr', '३', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/05', 'hi', 'लगातार आत्म-आरोप, या अपराध या पाप के निश्चित लेकिन फिर भी तर्कसंगत विचार। भविष्य के प्रति निराशा बढ़ती जा रही है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/05', 'mr', 'सतत स्वत:वर आरोप, किंवा अपराधीपणा किंवा पापाची निश्चित परंतु तरीही तर्कसंगत कल्पना. भविष्याबद्दल अधिकाधिक निराशावादी.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/06', 'hi', '5', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/06', 'mr', '५', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/07', 'hi', 'बर्बादी, पश्चाताप या न छुड़ाए जा सकने वाले पाप का भ्रम। आत्म-आरोप जो बेतुके और अटल हैं।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/009/07', 'mr', 'नाश, पश्चाताप किंवा अपरिहार्य पापाची भ्रांत. स्वत:वर केलेले आरोप जे निरर्थक आणि अबाधित आहेत.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/01', 'hi', 'जीवन का आनंद लेता है या जैसा मिलता है वैसा ही लेता है।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/01', 'mr', 'जीवन आनंदात घालवतो किंवा ते जसे येते तसे स्वीकारतो.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/02', 'hi', '1', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/02', 'mr', '१', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/03', 'hi', 'जीवन से थक गया हूँ. केवल क्षणभंगुर आत्मघाती विचार।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/03', 'mr', 'आयुष्यामुळे थकलो. क्षणिक आत्मघाती विचार.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/04', 'hi', '3', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/04', 'mr', '३', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/05', 'hi', 'शायद मर जाना ही बेहतर होगा. आत्महत्या के विचार आम हैं, और आत्महत्या को एक संभावित समाधान माना जाता है, लेकिन बिना किसी विशिष्ट योजना या इरादे के।', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/05', 'mr', 'कदाचित मरायला जाणे अधिक श्रेयस्कर ठरेल. आत्मघाती विचार सामान्य आहेत आणि आत्महत्येला संभाव्य उपाय म्हणून मानले जाते, परंतु विशिष्ट योजना किंवा हेतूशिवाय.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/06', 'hi', '5', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/06', 'mr', '५', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/07', 'hi', 'अवसर पड़ने पर आत्महत्या की स्पष्ट योजनाएँ बनाना। आत्महत्या के लिए सक्रिय तैयारी.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('MADRS/010/07', 'mr', 'संधी मिळेल तेव्हा आत्महत्येची स्पष्ट योजना. आत्महत्येची सक्रिय तयारी.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
