  ('PFS-16/016/05', 'mr', 'तीव्रपणे सहमत', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/01', 'hi', 'सामान्य, चलने, मुड़ने और एक साथ चलने में कोई कठिनाई नहीं (एक गलत कदम तक की अनुमति)', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/01', 'mr', 'सामान्य, चालताना, वळताना आणि चालताना (एक चुकीची पायरी परवानगी) चालताना कोणतीही अडचण नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/02', 'hi', 'थोड़ी सी कठिनाइयाँ, केवल एक साथ लगातार 10 कदम चलने पर ही दिखाई देती हैं', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/02', 'mr', 'थोड्या अडचणी, सलग १० पावले एकत्र चालत असतानाच दृश्यमान.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/03', 'hi', 'स्पष्ट रूप से असामान्य, एक साथ चलना >10 कदम संभव नहीं', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/03', 'mr', 'स्पष्टपणे अस्वाभाविक, टाँडम वॉकिंग >१० पावले शक्य नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/04', 'hi', 'काफ़ी लड़खड़ाहट, आधे-मोड़ में कठिनाइयाँ, लेकिन बिना सहारे के', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/04', 'mr', 'लक्षणीय धक्कादायक, अर्धा वळण कठीण, परंतु आधार नाही.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/05', 'hi', 'चिह्नित चौंका देने वाला, दीवार के रुक-रुक कर समर्थन की आवश्यकता', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/05', 'mr', 'धक्कादायक, भिंतीच्या अधूनमधून येणाऱ्या पाठिंब्याची आवश्यकता होती.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/06', 'hi', 'गंभीर लड़खड़ाहट, एक छड़ी का स्थायी सहारा या एक हाथ का हल्का सहारा आवश्यक', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/06', 'mr', 'गंभीर धक्का, एका हाताने एक काठी किंवा हलक्या हाताने आधार आवश्यक.', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/07', 'hi', 'केवल मजबूत समर्थन के साथ 10 मीटर से अधिक चलना (दो विशेष छड़ें या घुमक्कड़ या साथ में व्यक्ति)', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/07', 'mr', 'चालणे > १० मीटर केवळ जोरदार आधार घेऊन (दोन विशेष काठ्या किंवा घुमट किंवा सोबत असलेली व्यक्ती)', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/08', 'hi', 'केवल मजबूत समर्थन के साथ <10 मीटर चलना (दो विशेष छड़ें या घुमक्कड़ या साथ में व्यक्ति)', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/08', 'mr', 'जोरदार आधार घेऊन फक्त १० मीटर चालणे (दोन विशेष काठ्या किंवा घुमट किंवा सोबत असलेली व्यक्ती).', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/09', 'hi', 'चलने में असमर्थ, सहारा भी दिया', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/001/09', 'mr', 'चालता चालता, आधार घेत असतानाही', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/002/01', 'hi', 'सामान्य, 10 सेकंड से अधिक समय तक एक साथ खड़े रहने में सक्षम', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
  ('SARA/002/01', 'mr', 'सामान्य, १० सेकंदांपेक्षा जास्त वेळ एकत्र उभे राहू शकते', '2026-07-13T08:34:09.787168+00:00'::timestamptz),
